  "ev.hsn6": "ଆଇଟମ୍ {n}: ଇ-ଇନଭଏସରେ 6 ବା 8 ଅଙ୍କର HSN/SAC କୋଡ୍ ଦରକାର (4 ଅଙ୍କ କେବଳ ₹5 କୋଟିରୁ କମ୍ ବିଜନେସ ପାଇଁ, ଯେଉଁମାନେ ଇ-ଇନଭଏସ କରନ୍ତି ନାହିଁ)।",
  "ev.old30": "ଏହି ଇନଭଏସ 30 ବା ଅଧିକ ଦିନ ପୁରୁଣା। ₹10 କୋଟି ବା ଅଧିକ ଟର୍ଣ୍ଣଓଭରରେ ପୋର୍ଟାଲ ଏହାକୁ ଆଉ ରେଜିଷ୍ଟର କରେ ନାହିଁ। ନୂଆ ଇନଭଏସ ବନାଇବା ପୂର୍ବରୁ ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କୁ ପଚାରନ୍ତୁ।",
  "ev.lt5": "ଇ-ଇନଭଏସ ଆପଣଙ୍କ ପାଇଁ ବାଧ୍ୟତାମୂଳକ ନୁହେଁ, ଯେପର୍ଯ୍ୟନ୍ତ 2017-18 ଠାରୁ କୌଣସି ବର୍ଷ ଆପଣଙ୍କ ଟର୍ଣ୍ଣଓଭର ₹5 କୋଟି ପାର ହୋଇନାହିଁ।",
  "ev.old180": "180 ଦିନରୁ ପୁରୁଣା ଡକ୍ୟୁମେଣ୍ଟର ଇ-ୱେ ବିଲ ପୋର୍ଟାଲ ବନାଏ ନାହିଁ।",
  "ev.smallst": "{st} ଭିତରେ ଇ-ୱେ ବିଲ ସାଧାରଣତଃ ₹{v}ରୁ ଅଧିକ ହେଲେ ହିଁ ଦରକାର (ଅନ୍ୟ ରାଜ୍ୟକୁ ₹50,000ରୁ ଅଧିକ; ଅନ୍ୟ ରାଜ୍ୟକୁ ଯାଉଥିବା ଜବ୍ ୱାର୍କ ଓ ହସ୍ତଶିଳ୍ପରେ ଯେକୌଣସି ମୂଲ୍ୟରେ ଦରକାର)।",
  "ev.fromirn": "ଆପଣଙ୍କ ବିଜନେସକୁ ଇ-ଇନଭଏସ ବନାଇବାକୁ ପଡୁଥିଲେ, ଏହି ଇନଭଏସର ଇ-ୱେ ବିଲ ପୋର୍ଟାଲ କେବଳ ଏହାର IRNରୁ ବନାଏ: “ଇ-ଇନଭଏସ୍ ସହ ଇ-ୱେ ବିଲ୍ ମଧ୍ୟ କରନ୍ତୁ”ରେ ଟିକ୍ ଦିଅନ୍ତୁ ଓ ଇ-ଇନଭଏସ ଫାଇଲ ବନାନ୍ତୁ।",
  "ev.tidchk": "ଟ୍ରାନ୍ସପୋର୍ଟର IDର ଶେଷ ଅକ୍ଷର ମେଳ ଖାଉନାହିଁ। ଟାଇପିଂ ଭୁଲ ନୁହେଁ ତ, ଥରେ ଯାଞ୍ଚ କରନ୍ତୁ।",
  "ei.rmnote": "ଆପଣ ଏହି IRN ପୋର୍ଟାଲରେ କ୍ୟାନସେଲ କରିଥିଲେ, ଏହି ଇନଭଏସ ନମ୍ବର ଆଉ କେବେ ରେଜିଷ୍ଟର ହେବ ନାହିଁ। ଠିକ୍ ଇନଭଏସ ନୂଆ ନମ୍ବରରେ ବନାନ୍ତୁ।",
