  "v.b2c": "GSTIN ନଥିବା କଷ୍ଟମରଙ୍କୁ ₹50,000 ବା ଅଧିକ ବିଲରେ GST ନିୟମ ଅନୁସାରେ କଷ୍ଟମରଙ୍କ ନାମ, ଠିକଣା ଓ ରାଜ୍ୟ ଦରକାର।",
  "c.r28": "1 ଫେବୃଆରୀ 2026ରୁ 28% GST ହଟାଯାଇଛି (ସେହି ଜିନିଷ ଏବେ 40% ବା 18%ରେ)। ତଥାପି 28% ସହ ସେଭ କରିବେ?",
  "c.cash2l": "ଇନକମ ଟ୍ୟାକ୍ସ ଆଇନରେ ଗୋଟିଏ ବିଲ ପାଇଁ ₹2 ଲକ୍ଷ ବା ଅଧିକ ନଗଦ ନେବା ମନା (ଜରିମାନା ସେତିକି ରାଶି)। ତଥାପି ସେଭ କରିବେ?",
