  "v.sigst": "ସେଲ୍ଫ ଇନଭଏସରେ ଆପଣଙ୍କ GSTIN ଦରକାର: କେବଳ ରେଜିଷ୍ଟର୍ଡ ବାୟର ଏହା ଦିଅନ୍ତି।",
  "v.recv": "ସାମଗ୍ରୀ ବା ସର୍ଭିସ ଯେଉଁ ଦିନ ମିଳିଲା ସେହି ତାରିଖ ଲେଖନ୍ତୁ।",
  "c.si30": "ଏହି ସେଲ୍ଫ ଇନଭଏସର ତାରିଖ ସାମଗ୍ରୀ ବା ସର୍ଭିସ ମିଳିବାର 30 ଦିନରୁ ଅଧିକ ପରେ। ନିୟମରେ 30 ଦିନ ଭିତରେ ବନାଇବାକୁ କୁହାଯାଇଛି। ତଥାପି ସେଭ କରିବେ?",
  "k.ref": "ଆଡଭାନ୍ସ ଫେରସ୍ତ",
  "kh.ref": "କିଛି ସପ୍ଲାଇ ନହେବାରୁ ଆଡଭାନ୍ସର ଟଙ୍କା ଫେରାଇଦିଆଗଲା। GST ନିୟମରେ ଏହାକୁ ରିଫଣ୍ଡ ଭାଉଚର୍ କୁହାଯାଏ।",
  "s.gstadv": "ଏହି ଆଡଭାନ୍ସରେ GST ଧରାଯାଇଛି (ସର୍ଭିସ)",
  "s.h.gstadv": "ସର୍ଭିସ ପାଇଁ ମିଳିଥିବା ଆଡଭାନ୍ସରେ ଟିକ୍ ଦିଅନ୍ତୁ: ତେବେ ରସିଦଟି ରିସିପ୍ଟ ଭାଉଚର୍ ହୋଇଯିବ ଓ ଭିତରେ ଥିବା GST ଦେଖାଇବ। ସାମଗ୍ରୀର ଆଡଭାନ୍ସରେ GST ଲାଗେ ନାହିଁ; ସାଧାରଣ ଆଡଭାନ୍ସ ରସିଦ ହିଁ ରିସିପ୍ଟ ଭାଉଚର୍ କାମ କରେ।",
