  "s.h.rcm": "ଯେପରି ଅଣରେଜିଷ୍ଟର୍ଡ ସପ୍ଲାୟର ବା ରିଭର୍ସ ଚାର୍ଜରେ ଗୁଡ୍ସ ଟ୍ରାନ୍ସପୋର୍ଟ ଏଜେନ୍ସିକୁ ପେମେଣ୍ଟ।",
  "s.rcmrate": "ରିଭର୍ସ ଚାର୍ଜ GST ରେଟ୍ %",
  "c.nopan": "ଆପଣ TDS କାଟୁଛନ୍ତି କିନ୍ତୁ ଯାହାଙ୍କୁ ଟଙ୍କା ଦେଉଛନ୍ତି ତାଙ୍କ PAN ଖାଲି। PAN ନଥିଲେ TDS ସାଧାରଣତଃ 20% (ସାମଗ୍ରୀ କିଣିବାରେ 5%)। ତଥାପି ସେଭ କରିବେ?",
