  "app.helpp": "billing., cash-memo. ଓ credit-note. ରେ ତିଆରି ବିଲ ଏଠାରେ ନିଜେ ଦେଖାଯାଏ। ମିଳିଥିବା ଓ ଦେଇଥିବା ଟଙ୍କା ଏଠାରେ ଲେଖନ୍ତୁ; ଆପ ତାକୁ ବିଲ ସହ ଯୋଡେ, ଆଡଭାନ୍ସ ରଖେ ଓ ବାକି ଏବଂ ହାତ କ୍ୟାସ ବାହାର କରେ।",
