  "bk.tpl": "Excel ଟେମ୍ପଲେଟ୍ ଡାଉନଲୋଡ୍ କରନ୍ତୁ",
  "bk.choose": "ଆପଣଙ୍କ Excel ବା CSV ଫାଇଲ୍ ବାଛନ୍ତୁ",
  "bk.h.s2": "ପ୍ରତି ଆଇଟମ୍‌ରେ ଗୋଟିଏ ଧାଡ଼ି। ଏକା ଇନଭଏସ୍ ନମ୍ବରର ଧାଡ଼ିଗୁଡ଼ିକ ମିଶି ଗୋଟିଏ ଇନଭଏସ୍ ହୁଏ। ସ୍ତମ୍ଭର ନାମ ଆମ ପରି ହେଲେ ଆପଣଙ୍କ ନିଜ ସିଟ୍ ମଧ୍ୟ ଚାଲିବ।",
  "bk.h.s2e": "ପ୍ରତି ଆଇଟମ୍‌ରେ ଗୋଟିଏ ଧାଡ଼ି। ଏକା ଡକ୍ୟୁମେଣ୍ଟ ନମ୍ବରର ଧାଡ଼ିଗୁଡ଼ିକ ମିଶି ଗୋଟିଏ ଇ-ୱେ ବିଲ୍ ହୁଏ। ଗାଡ଼ିର ଘର ଖାଲି ରଖିଲେ କେବଳ Part A ହେବ, ଗାଡ଼ି ପରେ ଯୋଡ଼ିପାରିବେ।",
  "bk.reading": "ଫାଇଲ୍ ପଢ଼ାଯାଉଛି…",
  "bk.xls": "ଏହା ପୁରୁଣା .xls ଫାଇଲ୍। Excel ରେ File › Save As › Excel Workbook (.xlsx) ବା CSV UTF-8 ବାଛନ୍ତୁ, ତା’ପରେ ସେହି ଫାଇଲ୍ ବାଛନ୍ତୁ।",
  "bk.badfile": "ଏହି ଫାଇଲ୍ ପଢ଼ିହେଲା ନାହିଁ। ଗୋଟିଏ .xlsx ବା .csv ଫାଇଲ୍ ବାଛନ୍ତୁ।",
  "bk.nohead": "ସ୍ତମ୍ଭର ନାମ ମିଳିଲା ନାହିଁ (ଅତି କମରେ ଡକ୍ୟୁମେଣ୍ଟ ନମ୍ବର ଓ ଆଇଟମ୍ ଥିବା ଦରକାର)। ଆମ ଟେମ୍ପଲେଟ୍‌ରୁ ଆରମ୍ଭ କରନ୍ତୁ।",
