  "bk.h.s3": "ଅପଲୋଡ୍ ପରେ ପୋର୍ଟାଲରୁ ରେଜଲ୍ଟ (JSON ବା Excel) ଡାଉନଲୋଡ୍ କରି ଏଠାରେ ବାଛନ୍ତୁ। IRN, Ack ନମ୍ବର ଓ ସାଇନ୍ କରାଯାଇଥିବା QR କୋଡ୍ ସେଭ୍ ହୋଇଥିବା ପ୍ରତ୍ୟେକ ଇନଭଏସ୍‌ରେ ବସିଯିବ, ପ୍ରିଣ୍ଟ ପାଇଁ ପ୍ରସ୍ତୁତ।",
  "bk.h.s3e": "ବନାଇବା ପରେ ପୋର୍ଟାଲରୁ ରେଜଲ୍ଟ ଡାଉନଲୋଡ୍ କରି ଏଠାରେ ବାଛନ୍ତୁ। ଇ-ୱେ ବିଲ୍ ନମ୍ବର ସେଭ୍ ହୋଇଥିବା ଇନଭଏସ୍‌ରେ ଓ ତଳର ଗାଡ଼ି ଫାଇଲ୍‌ରେ ବସିଯିବ।",
