  'td.q': 'କେବଳ ଗତ ବର୍ଷ ଆପଣଙ୍କ ଟର୍ନଓଭର୍ ₹10 କୋଟିରୁ ଅଧିକ ଥିଲେ କାଟନ୍ତୁ, ଆଉ ଏହି ବିକ୍ରେତାଙ୍କ ଠାରୁ ବର୍ଷର କିଣାର ₹50 ଲକ୍ଷରୁ ଅଧିକ ଅଂଶ ଉପରେ ହିଁ।',
  'td.ib': 'ଟ୍ୟାକ୍ସ ଅଡିଟ୍ ଅଧୀନ ନଥିବା ବ୍ୟକ୍ତି ଦେଉଥିବା ଘରଭଡ଼ାରେ TDS ଥରେ ମାତ୍ର କଟାଯାଏ, ବର୍ଷର ବା ଭଡ଼ା ଚୁକ୍ତିର ଶେଷ ମାସର ଭଡ଼ାରୁ।',
  'td.oldnote': '1 ଏପ୍ରିଲ୍ 2026 ପୂର୍ବର ପେମେଣ୍ଟ ପାଇଁ Income-tax Act, 1961 ଲାଗୁ ହୁଏ: ପୁରୁଣା ଧାରା ନମ୍ବର ବ୍ୟବହାର କରନ୍ତୁ।',
