  "hs.rate": "GST ରେଟ୍ ପୂରା କୋଡ୍ ଓ ଅଫିସିଆଲ ରେଟ୍ ନୋଟିଫିକେସନର ବିବରଣୀ ଉପରେ ନିର୍ଭର କରେ, ଯାହା 22 ସେପ୍ଟେମ୍ବର 2025 ରେ ଓ ପୁଣି 2026 ରେ ବଦଳିଲା। ଠିକ୍ ରେଟ୍ ତଳର ଅଫିସିଆଲ ସର୍ଚ୍ଚରେ ଦେଖନ୍ତୁ।",
