  "b1.cdel": "{x} ଡିଲିଟ୍ କରିବେ? ଏହା 30 ଦିନ ରିସାଇକେଲ୍ ବିନ୍‌ରେ ରହିବ, ସେଠାରୁ ରିଷ୍ଟୋର୍ କରିହେବ।",
  "b1.binned": "ରିସାଇକେଲ୍ ବିନ୍‌କୁ ଗଲା। 30 ଦିନ ପର୍ଯ୍ୟନ୍ତ ରିଷ୍ଟୋର୍ କରିହେବ।",
