  "b1.nolog": "ଏବେ ପର୍ଯ୍ୟନ୍ତ କୌଣସି ବଦଳ ଲେଖା ହୋଇନାହିଁ।",
  "b1.thisdev": "ଏହି ଡିଭାଇସ୍",
  "b1.logp": "ଯେକୌଣସି Nivesh Sahayak ସାଇଟ୍‌ରେ ବିଜନେସ୍, ପାର୍ଟି, ଆଇଟମ୍ କିମ୍ବା ଡକ୍ୟୁମେଣ୍ଟ ଯୋଡ଼ା, ବଦଳ, ଡିଲିଟ୍ ବା ରିଷ୍ଟୋର୍ ହେଲେ ତାରିଖ, ସମୟ, ନାମ ଓ କ'ଣ ବଦଳିଲା ସହ ଏଠାରେ ଲେଖାଯାଏ। ଏହି ଏଣ୍ଟ୍ରି ବଦଳାଇ ବା ହଟାଇ ହୁଏ ନାହିଁ।",
  "b1.logrule": "1 ଏପ୍ରିଲ 2023 ରୁ କମ୍ପାନିଗୁଡ଼ିକୁ ଏପରି ଆକାଉଣ୍ଟସ୍ ସଫ୍ଟୱେର୍ ବ୍ୟବହାର କରିବାକୁ ପଡ଼େ ଯାହା ଏହି ଅଡିଟ୍ ଟ୍ରେଲ୍ ରଖେ (କମ୍ପାନିଜ୍ (ଆକାଉଣ୍ଟସ୍) ରୁଲ୍ସ 2014, ନିୟମ 3(1))। ଏହା ଏହି ବ୍ରାଉଜର୍ ଓ ଆପଣଙ୍କ ବ୍ୟାକଅପ୍ ଫାଇଲ୍‌ରେ ରହେ।",
  "b1.logmore": "{n} ମଧ୍ୟରୁ ନୂଆ 300 ଦେଖାଉଛି। ସବୁ ପାଇଁ Excel ଫାଇଲ୍ ଡାଉନଲୋଡ୍ କରନ୍ତୁ।",
