  "b1.h_who": "ଏହି ଡିଭାଇସ୍‌ରେ କରାଯାଇଥିବା ପ୍ରତି ବଦଳ ସହ ବଦଳର ରେକର୍ଡରେ ଦେଖାଯିବ।",
  "b1.lock": "ଏହି ତାରିଖ ଆଗର ଡକ୍ୟୁମେଣ୍ଟ ଲକ୍ କରନ୍ତୁ",
  "b1.h_lock": "ଏହି ଦିନ ଆଗ ତାରିଖର ଡକ୍ୟୁମେଣ୍ଟ କୌଣସି ସାଇଟ୍‌ରେ ଯୋଡ଼ି, ବଦଳାଇ ବା ଡିଲିଟ୍ କରିହେବ ନାହିଁ (ପେମେଣ୍ଟ ମିଳିଲା ଚିହ୍ନ ଦେବା ଚାଲିବ)। GST ରିଟର୍ନ ଦାଖଲ ବା ହିସାବ ବନ୍ଦ ପରେ ବ୍ୟବହାର କରନ୍ତୁ।",
  "b1.lockc": "{d} ଆଗ ତାରିଖର ସବୁ ଡକ୍ୟୁମେଣ୍ଟ ଲକ୍ କରିବେ? ଏହି ତାରିଖ ହଟାଇବା ପର୍ଯ୍ୟନ୍ତ ବଦଳାଇ ହେବ ନାହିଁ।",
  "b1.unlockc": "ପୁରୁଣା ଡକ୍ୟୁମେଣ୍ଟ ପୁଣି ବଦଳାଇବା ପାଇଁ ଅନଲକ୍ କରିବେ?",
  "b1.locked": "ଲକ୍ ଅଛି: {d} ଆଗ ତାରିଖର ଡକ୍ୟୁମେଣ୍ଟ ବଦଳାଇ ହେବ ନାହିଁ। ପ୍ରଥମେ ସେଟିଂସ୍ ଓ ସେଭ୍ ଡାଟା › ସେଟିଂସ୍‌ରେ ଲକ୍ ତାରିଖ ହଟାନ୍ତୁ।",
