  "b1.forgot": "PIN ଭୁଲିଗଲେ?",
  "b1.forgotp": "PIN ଦେଖାଇ ବା ରିସେଟ୍ କରିହେବ ନାହିଁ। ଭିତରକୁ ଆସିବାକୁ ଏହି ବ୍ରାଉଜର୍‌ର ଡାଟା ଲିଭାନ୍ତୁ ଓ ଆପଣଙ୍କ ଶେଷ ବ୍ୟାକଅପ୍ ଫାଇଲ୍ ରିଷ୍ଟୋର୍ କରନ୍ତୁ। ସେହି ବ୍ୟାକଅପ୍ ପରେ ସେଭ୍ ହୋଇଥିବା ସବୁ ଚାଲିଯିବ।",
  "b1.erase": "ଏହି ବ୍ରାଉଜର୍‌ର ଡାଟା ଲିଭାନ୍ତୁ",
  "b1.erase_c1": "ଏହି ବ୍ରାଉଜର୍‌ରେ ସେଭ୍ ଥିବା ପ୍ରତି ବିଜନେସ୍, ପାର୍ଟି, ଆଇଟମ୍ ଓ ଡକ୍ୟୁମେଣ୍ଟ ଲିଭାଇବେ? କେବଳ ଆପଣଙ୍କ ବ୍ୟାକଅପ୍ ଫାଇଲ୍ ସେଗୁଡ଼ିକୁ ଫେରାଇ ପାରିବ।",
  "b1.erased": "ଲିଭାଗଲା। ଏବେ ଆପଣଙ୍କ ବ୍ୟାକଅପ୍ ଫାଇଲ୍ ବାଛନ୍ତୁ।",
  "b1.wiz": "ଏକ ମିନିଟ୍‌ରେ ଆରମ୍ଭ କରନ୍ତୁ",
  "b1.wizp": "ଆପଣଙ୍କ ବିଜନେସ୍‌ର ବିବରଣୀ ପ୍ରତି ବିଲ୍‌ରେ ଛପାଯାଏ। ପରେ ବଦଳାଇ ଓ ଆଉ ବିଜନେସ୍ ଯୋଡ଼ି ପାରିବେ।",
  "b1.wiz_gst": "GST ରେଜିଷ୍ଟ୍ରେସନ୍ ନଥିଲେ ଖାଲି ରଖନ୍ତୁ।",
  "b1.wiz_go": "ସେଭ୍ କରି ଆରମ୍ଭ କରନ୍ତୁ",
  "b1.wiz_done": "ଆପଣଙ୍କ ବିଜନେସ୍ ସେଭ୍ ହେଲା। ଏବେ ଗ୍ରାହକ ଓ ଆଇଟମ୍ ଯୋଡ଼ନ୍ତୁ, କିମ୍ବା ପ୍ରଥମ ବିଲ୍ ତିଆରି କରନ୍ତୁ।",
  "b1.samp_try": "ପ୍ରଥମେ ସାମ୍ପଲ୍ ଡାଟାରେ ଦେଖନ୍ତୁ",
  "b1.samp_h": "ସାମ୍ପଲ୍ ଡାଟା ହେଉଛି \"Sharma Hardware (sample)\" ନାମକ ଏକ ବନାଉଟି ବିଜନେସ୍, ଯେଉଁଥିରେ ଗ୍ରାହକ, ଆଇଟମ୍, ବିଲ୍, ଗୋଟିଏ ପେମେଣ୍ଟ ଓ ଗୋଟିଏ କିଣା ଅଛି, ସବୁଥିରେ ସାମ୍ପଲ୍ ଲେଖା। ଏକ ଟ୍ୟାପ୍‌ରେ ସବୁ ହଟିଯାଏ।",
  "b1.samp_on": "ସାମ୍ପଲ୍ ଡାଟା ଚାଲୁ: ସାମ୍ପଲ୍ ଲେଖା ରେକର୍ଡ ବନାଉଟି।",
  "b1.samp_rm": "ସବୁ ସାମ୍ପଲ୍ ରେକର୍ଡ ହଟାନ୍ତୁ",
  "b1.samp_rmc": "ପ୍ରତି ସାମ୍ପଲ୍ ରେକର୍ଡ ହଟାଇବେ? ଆପଣଙ୍କ ନିଜ ରେକର୍ଡ ରହିବ।",
  "b1.samp_gone": "{n} ଟି ସାମ୍ପଲ୍ ରେକର୍ଡ ହଟାଗଲା।",
  "b1.samp_added": "ସାମ୍ପଲ୍ ଡାଟା ଯୋଡ଼ାଗଲା। ଦେଖିନିଅନ୍ତୁ, ତାପରେ ଏକ ଟ୍ୟାପ୍‌ରେ ହଟାନ୍ତୁ।",
  "b1.sample": "ସାମ୍ପଲ୍",
