  "b1.rp_p": "ପ୍ରତି ବଟନ୍ ବଛା ତାରିଖର Excel ଫାଇଲ୍ ଡାଉନଲୋଡ୍ କରେ। କଲମ୍ ନାମ ଇଂରାଜୀରେ, ଯାହାଦ୍ୱାରା ଯେକୌଣସି ଆକାଉଣ୍ଟାଣ୍ଟ ପଢ଼ିପାରିବେ।",
