  "b2.fadup": "{n} ନାମରେ ଆସେଟ୍ ଆଗରୁ ସେଭ୍ ଅଛି। ଏହାକୁ ଅନ୍ୟ ନାମ ଦିଅନ୍ତୁ (ଯେପରି ଗୋଟିଏ ନମ୍ବର ଯୋଡ଼ନ୍ତୁ)।",
