  "b2.dep": "ଡେପ୍ରିସିଏସନ",
  "b2.closewdv": "କ୍ଲୋଜିଂ WDV",
  "b2.gain": "ଲାଭ {a}: ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କୁ ପଚାରନ୍ତୁ",
  "b2.farules": "ଡେପ୍ରିସିଏସନ କିପରି ହିସାବ ହୁଏ",
  "b2.farule1": "ଖାତାର ଡେପ୍ରିସିଏସନ କମ୍ପାନିଜ୍ ଆକ୍ଟ, 2013 ର ଶିଡ୍ୟୁଲ II ଅନୁସାରେ: ପ୍ରତି ପ୍ରକାର ଆସେଟ୍‌ର ଏକ ବ୍ୟବହାର ଅବଧି ଅଛି (ଯେପରି କମ୍ପ୍ୟୁଟର 3 ବର୍ଷ, ଫର୍ଣ୍ଣିଚର 10 ବର୍ଷ, ପ୍ଲାଣ୍ଟ ଓ ମେସିନାରି 15 ବର୍ଷ, କାର୍ 8 ବର୍ଷ), ବାକି ଭାଲ୍ୟୁ ସାଧାରଣତଃ ଦାମର 5% ରୁ ଅଧିକ ହୁଏ ନାହିଁ, ଏବଂ ବର୍ଷ ମଝିରେ ଯୋଡ଼ା ବା ବିକା ଆସେଟ୍‌ରେ କେବଳ ବ୍ୟବହାର ଦିନର ଡେପ୍ରିସିଏସନ ଲାଗେ। ଷ୍ଟ୍ରେଟ୍ ଲାଇନ୍ (SLM: ପ୍ରତି ବର୍ଷ ସମାନ ଟଙ୍କା) ବା ରିଟନ୍ ଡାଉନ୍ ଭାଲ୍ୟୁ (WDV: ବାକି ଟଙ୍କାରେ ନିର୍ଦ୍ଦିଷ୍ଟ ରେଟ୍) ବାଛନ୍ତୁ। ପ୍ରୋପ୍ରାଇଟର ଓ ଫର୍ମ ପ୍ରାୟତଃ ଏହି ପଦ୍ଧତି ଅନୁସରଣ କରନ୍ତି; ନିଷ୍ପତ୍ତି ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କର।",
  "b2.farule2": "ଇନକମ୍ ଟ୍ୟାକ୍ସ ଡେପ୍ରିସିଏସନ ପ୍ରତି ବ୍ଲକ୍‌ର ଅଲଗା ହିସାବ ହୁଏ: ବ୍ଲକ୍ ରେଟ୍‌ରେ ରିଟନ୍ ଡାଉନ୍ ଭାଲ୍ୟୁ (ଯେପରି ପ୍ଲାଣ୍ଟ ଓ ମେସିନାରି 15%, ଫର୍ଣ୍ଣିଚର 10%, କମ୍ପ୍ୟୁଟର 40%), ବର୍ଷରେ 180 ଦିନରୁ କମ୍ ବ୍ୟବହୃତ ଆସେଟ୍‌ରେ ଅଧା ରେଟ୍, ଏବଂ ବିକ୍ରି ଟଙ୍କା ବ୍ଲକ୍‌ରୁ କମେ। ଏହା କେବଳ ଇନକମ୍ ଟ୍ୟାକ୍ସ ରିଟର୍ଣ୍ଣ ପାଇଁ, ଖାତାରେ କେବେ ପକାଯାଏ ନାହିଁ। ଭରାଯାଇଥିବା ରେଟ୍ ସାଧାରଣ ବ୍ଲକ୍ ରେଟ୍: ଆପଣଙ୍କ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କ ସହ ନିଶ୍ଚିତ କରନ୍ତୁ, ବିଶେଷକରି 1 ଅପ୍ରେଲ 2026 ରୁ ଇନକମ୍-ଟ୍ୟାକ୍ସ ଆକ୍ଟ, 2025 ଅଧୀନ ବର୍ଷ ପାଇଁ।",
  "b2.farule3": "ଆପଣ 'ଡେପ୍ରିସିଏସନ ପକାନ୍ତୁ' ଦବାଇଲେ ହିଁ ଡେପ୍ରିସିଏସନ ଖାତାକୁ ଯାଏ: ବର୍ଷର ଶେଷ ଦିନର (ବା ବର୍ଷ ମଝିରେ ଆଜିର) ଜର୍ଣ୍ଣାଲ ଏଣ୍ଟ୍ରି ଡେପ୍ରିସିଏସନକୁ ଡେବିଟ୍ କରେ ଏବଂ ପ୍ରତି ଆସେଟ୍ କମାଏ। ପରେ ଆସେଟ୍ ବଦଳାଇଲେ ପୁଣି ପକାନ୍ତୁ, କେବଳ ପାର୍ଥକ୍ୟ ଯୋଡ଼ିହେବ।",
