  "b2.carryh": "ଏହି ଡାଟା ହୋମରେ କିଛି ନେବା ଦରକାର ନାହିଁ: ପାର୍ଟି ବାଲାନ୍ସ, କ୍ୟାସ୍, ବ୍ୟାଙ୍କ ଓ ଷ୍ଟକ୍ ନିଜେ ନୂଆ ବର୍ଷରେ ଚାଲୁ ରହେ, କାରଣ ଆପ୍ ପ୍ରତି ସେଭ୍ ରେକର୍ଡରୁ ହିସାବ କରେ।",
  "b2.numh": "ପ୍ରତି ଫାଇନାନ୍ସିଆଲ ଇୟରରେ ଡକ୍ୟୁମେଣ୍ଟ ନମ୍ବର ପୁଣି 001 ରୁ ଆରମ୍ଭ (ଯେପରି INV/27-28/001), ସେହି ପ୍ରିଫିକ୍ସ ସହ, ତେଣୁ ନୂଆ ବର୍ଷ ପାଇଁ କିଛି ବଦଳାଇବାକୁ ପଡ଼େ ନାହିଁ।",
  "b2.closet": "ବର୍ଷ ବନ୍ଦ କରନ୍ତୁ",
  "b2.closeh": "ବର୍ଷ ବନ୍ଦ କଲେ ତାହା କେବଳ ପଢ଼ିବା ପାଇଁ: ଆପ୍ ଓ ପ୍ରତି ଡକ୍ୟୁମେଣ୍ଟ ମେକର ତା ଭିତରର ତାରିଖର କିଛି ସେଭ୍, ବଦଳ ବା ଡିଲିଟ୍ କରିବାକୁ ଦିଏ ନାହିଁ। ଆପଣ ଯେକୌଣସି ସମୟରେ ଏଠାରେ ପୁଣି ଖୋଲିପାରିବେ।",
