  "b2.newfile": "ନୂଆ ବର୍ଷ ନୂଆ ଡାଟା ଫାଇଲରେ ଆରମ୍ଭ କରନ୍ତୁ",
  "b2.newfileh": "ନୂଆ ବ୍ରାଉଜରକୁ ଯାଉଛନ୍ତି ବା ନୂଆ କରି ଆରମ୍ଭ କରୁଛନ୍ତି? ଏହି ଫାଇଲରେ ଆପଣଙ୍କ ବ୍ୟବସାୟ, ଗ୍ରାହକ, ସପ୍ଲାୟର ଓ ଆଇଟମ୍, ଏବଂ 1 ଅପ୍ରେଲର ଓପନିଂ ବାଲାନ୍ସ ଅଛି: ପ୍ରତି ପାର୍ଟିର ବାଲାନ୍ସ, କ୍ୟାସ୍, ବ୍ୟାଙ୍କ, ହାରାହାରି ଦାମରେ ଷ୍ଟକ୍, ଏବଂ ଫିକ୍ସଡ୍ ଆସେଟ୍, ଲୋନ୍, GST, TDS ଓ ପୁଞ୍ଜି ପାଇଁ ଗୋଟିଏ ଜର୍ଣ୍ଣାଲ ଏଣ୍ଟ୍ରି (ବର୍ଷର ପ୍ରଫିଟ୍ ପୁଞ୍ଜିରେ ଅଛି)। ସେଠାରେ My data, ବ୍ୟାକଅପ୍‌ରେ ରିଷ୍ଟୋର କରନ୍ତୁ।",
