  "b3.gd.fail": "Google Drive ଅନୁରୋଧ ମାନିଲା ନାହିଁ (ଏରର୍ {code})। କିଛି ସମୟ ପରେ ଚେଷ୍ଟା କରନ୍ତୁ।",
  "b3.gd.badfile": "Drive ର ଫାଇଲଟି Nivesh Sahayak ର ସିଙ୍କ୍ ଫାଇଲ୍ ନୁହେଁ। କିଛି ବଦଳାଯାଇନାହିଁ।",
  "b3.gd.clash": "{n}ଟି ରେକର୍ଡ ଦୁଇଟି ଡିଭାଇସରେ ବଦଳିଛି",
  "b3.gd.clashp": "ସବୁଠାରୁ ନୂଆ ବଦଳ ରଖାଗଲା। ଏଗୁଡ଼ିକ ଅନ୍ୟ କପି: କୌଣସିଟି ଠିକ୍ ଥିଲେ ତାହାକୁ ଫେରାଇ ଆଣନ୍ତୁ।",
